set-variable.value:
@{
    string[] values;
    if (!context.Request.Headers.TryGetValue("x-business-invocation-id", out values) || values.Length == 0) return "generated-absent";
    if (values.Length != 1) return "generated-duplicate";
    if (!(bool)context.Variables["contoso.callerTrustedInvocationIssuer"]) return "generated-untrusted";
    var value = values[0];
    if (value == null || value.Length != 36 || !Regex.IsMatch(value, "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")) return "generated-invalid";
    return "accepted-trusted";
  }
